INSERT INTO articles (slug,title,excerpt,content,category,author,coverImage,seoTitle,seoDescription,status,publishedAt,authorId,createdAt,updatedAt) VALUES
('comprendre-une-clause-de-periode-dessai','Comprendre une clause de période d’essai','Durée, renouvellement, rupture : les repères essentiels pour lire une période d’essai sans se perdre dans le jargon.','## Pourquoi cette clause existe\n\nLa période d’essai permet à l’employeur et au salarié d’évaluer la relation de travail avant de s’engager durablement. Elle ne doit pas être confondue avec une période de formation ni avec un contrat provisoire.\n\n## Les trois questions à poser\n\nAvant de signer, vérifiez sa durée, les conditions prévues pour son renouvellement et la manière dont la rupture doit être annoncée. Ces éléments doivent être lisibles dans le contrat ou dans le document qui vous est remis.\n\n## Ce que le texte ne dit pas toujours\n\nUne clause n’est pas une autorisation générale de rompre n’importe comment. Le contexte, le délai de prévenance applicable et la réalité de l’évaluation comptent aussi. Conservez les échanges et demandez une explication écrite en cas de désaccord.\n\n> Cet article propose des repères de lecture et ne remplace pas l’examen d’une situation individuelle par un professionnel habilité.','Droit du travail','La rédaction',NULL,'Période d’essai : les repères essentiels | Droit de regard','Durée, renouvellement et rupture : comment lire une clause de période d’essai avec méthode.','published',NOW(),1,NOW(),NOW()),
('donnees-personnelles-comprendre-les-bons-reflexes','Données personnelles : les bons réflexes avant de cliquer','Collecte, consentement et réutilisation : une méthode simple pour comprendre ce que deviennent nos informations.','## Une donnée n’est jamais seulement technique\n\nUne adresse email, un numéro de téléphone ou une information de navigation peuvent permettre d’identifier une personne. Le premier réflexe consiste à demander pourquoi la donnée est collectée et combien de temps elle sera conservée.\n\n## Lire au-delà du bouton « accepter »\n\nUne politique de confidentialité utile explique les finalités, les destinataires et les droits disponibles. Si l’information est vague, cherchez la rubrique consacrée aux paramètres, au retrait du consentement ou à la suppression.\n\n## Une question de proportion\n\nLe fait qu’une information soit accessible ne signifie pas qu’elle puisse être réutilisée librement. La finalité annoncée, le contexte et les mesures de protection donnent le cadre de lecture.\n\n> Cet article est pédagogique et ne constitue pas un audit de conformité.','Droit numérique','La rédaction',NULL,'Données personnelles : les bons réflexes | Droit de regard','Une méthode de lecture pour comprendre la collecte et l’utilisation de ses données personnelles.','published',NOW(),1,NOW(),NOW()),
('lire-un-bail-avant-de-signer','Lire un bail avant de signer','Loyer, charges, durée et état des lieux : les points à regarder avant de remettre les clés.','## Commencer par les obligations principales\n\nUn bail organise une relation dans le temps. Avant de signer, repérez le montant du loyer, les charges, la date de prise d’effet et les conditions de révision.\n\n## Les annexes comptent\n\nL’état des lieux, les diagnostics et les documents remis avec le contrat ne sont pas de simples formalités. Ils permettent de comparer la situation au début et à la fin de la location.\n\n## Garder une trace\n\nPhotographies datées, échanges écrits et quittances forment une mémoire utile de la relation locative. En cas de difficulté, commencez par qualifier précisément le désaccord avant d’envoyer un message.\n\n> Les règles peuvent varier selon le type de logement et le lieu concerné ; faites vérifier votre situation si un litige se présente.','Droit du logement','La rédaction',NULL,'Lire un bail avant de signer : les points essentiels','Loyer, charges, annexes et état des lieux : les repères pour lire un bail d’habitation.','published',NOW(),1,NOW(),NOW()),
('contrat-commercial-questions-a-poser','Contrat commercial : cinq questions à poser avant de s’engager','Un contrat ne se lit pas uniquement à la dernière page. Voici une grille pour repérer les obligations, les risques et les marges de négociation.','## Qui doit quoi à qui ?\n\nCommencez par reformuler les obligations de chaque partie avec des verbes concrets : livrer, payer, maintenir, informer, garantir. Cette lecture fait ressortir les zones floues.\n\n## Que se passe-t-il si la relation se dégrade ?\n\nRegardez les délais, la mise en demeure, la suspension et la résiliation. Une clause bien rédigée décrit un chemin, pas seulement une sanction.\n\n## Quelle preuve conserver ?\n\nDevis, versions signées, bons de commande et échanges peuvent compléter le contrat. Organisez-les dès le début plutôt que lorsque le différend est déjà installé.\n\n> Pour un engagement important, une revue professionnelle du contrat reste recommandée.','Droit des affaires','La rédaction',NULL,'Contrat commercial : cinq questions à poser','Une grille de lecture simple pour comprendre les obligations et les risques d’un contrat commercial.','published',NOW(),1,NOW(),NOW()),
('quand-une-regle-change-comment-la-lire','Quand une règle change : comment suivre le mouvement','Entrée en vigueur, période transitoire et effets concrets : les repères pour ne pas confondre annonce et droit applicable.','## Une annonce n’est pas toujours une règle\n\nUne réforme peut être annoncée, votée, publiée puis entrer en vigueur à une date différente. La première question est donc de savoir quel texte est réellement applicable au moment où l’on agit.\n\n## Repérer la période transitoire\n\nCertaines règles distinguent les contrats déjà conclus, les situations nouvelles et les procédures en cours. Les dates et les dispositions transitoires sont souvent le vrai centre de la lecture.\n\n## Revenir à la situation concrète\n\nAprès le texte, revenez aux faits : qui est concerné, quelle décision doit être prise et quel document permet de la justifier ? Cette méthode évite de transformer une information générale en conclusion trop rapide.\n\n> Un article de revue aide à s’orienter ; il ne remplace pas une consultation adaptée à un dossier précis.','Repères juridiques','La rédaction',NULL,'Quand une règle change : comment la lire','Entrée en vigueur, période transitoire et effets concrets : les repères essentiels.','published',NOW(),1,NOW(),NOW());
